        "pm": "베를린 브란덴부르크 공항에서 시내까지 기차로 약 30분. 미테 지구에 체크인하고 브란덴부르크 문으로 걸어간다. 냉전 시절 동서를 가르는 장벽 바로 앞에 있던 문이 지금은 통일의 상징이 되었다. 운터 덴 린덴 대로를 따라 훔볼트 대학과 베벨 광장을 지난다.",
        "ev": "가볍게 독일식 저녁을 먹는다. 첫날이니 슈니첼이나 소시지 정도로 단순하게 가고 일찍 쉰다.",
        "tip": "숙소는 미테(Mitte) 지구를 권한다. 주요 역사 유적이 도보권이고 교통이 좋다. 베를린은 대중교통 검표가 불시에 이뤄지니 반드시 티켓을 개찰하자.",
