        "ev": "트로카데로 샤이오 궁 두 날개 사이에서 에펠탑 전체를 정면으로 담는다. 샹드마르스 공원을 가로질러 생제르맹데프레로 이동. 카페 드 플로르 앞을 지나며 사르트르·보부아르의 흔적을 느끼고 인근 비스트로에서 첫 파리 저녁. 정시마다 에펠탑 2만 개 섬광등이 5분간 켜진다.",
